 		return false, nil
 	}
 	if err != nil {
 		return false, fmt.Errorf("failed to check remote metadata branch: %w", err)
 	}

 	if localRef.Hash() == remoteRef.Hash() {
 		return false, nil
 	}

 	repoPath, err := getRepoPath(repo)
